// Палитра аспектов — премиум tier для тёмного UI.
//
// Принципы:
//   1. Все цвета сидят в одной полосе HSL L* 60-70% — ни один не «выпадает»
//      по яркости. Раньше БС (pistachio) светился ярче остальных, потому
//      что у него L=67%, а у Te/Fe/Se было L=30-50%.
//   2. Чистые, насыщенные тона (S=40-60%) без флуоресцентного зашкаливания.
//   3. Каждый цвет сохраняет психологическую семантику аспекта.
//   4. Соседние на колесе аспекты (Te-Ti, Fe-Fi, Se-Si, Ne-Ni) — разная
//      по яркости/насыщенности, не сливаются.
//
// Семантика каждого:
//   Te → luminous slate steel (металлический blue-grey, индустриал)
//   Ti → pearl platinum (светлый кристалл, ясность мысли)
//   Fe → luminous crimson rose (страстный рубиновый огонь)
//   Fi → radiant honey gold (золото нравственной ценности, тёплое)
//   Se → luminous burnt sienna (земля + огонь, активная природная воля)
//   Si → fresh pistachio (мягкая природа, уют, тело)
//   Ne → luminous electric indigo (искра видения, третий глаз)
//   Ni → luminous amethyst (мистика, время, подсознание)
export const ASPECT_COLORS = {
  Te: '#8FA8BD',  // luminous slate steel (cool metal, lit)
  Ti: '#DCE2EB',  // pearl platinum (bright crystal)
  Fe: '#D85160',  // luminous crimson rose
  Fi: '#E6C158',  // radiant honey gold
  Se: '#CC7152',  // luminous burnt sienna
  Si: '#A8D97B',  // fresh pistachio (без изменений)
  Ne: '#8975DD',  // luminous electric indigo
  Ni: '#B97FD2'   // luminous amethyst
}

export const ASPECT_KEYS = ['Te', 'Ti', 'Fe', 'Fi', 'Se', 'Si', 'Ne', 'Ni']

